    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case ComfortDemandQualifier_climateSupervisionProcess_comfortDemandQualifier_id =>
          val prefix = "ComfortDemandQualifier_climateSupervisionProcess_comfortDemandQualifier_RM_TestSuite"
