            st"""package scp_candidate.HVAC_Energy_Interface_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.HVAC_Energy_Interface_Supervisor._
                |
                |class ${suiteName} extends ComfortDemandQualifier_climateSupervisionProcess_comfortDemandQualifier_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
