  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.HVACSupervisor_Instance_climateSupervisionProcess_comfortDemandQualifier_postInit =>
        return (st"""// Begin test cases for HVACSupervisor_Instance_climateSupervisionProcess_comfortDemandQualifier_postInit
                    |
                    |test(s"HVACSupervisor_Instance_climateSupervisionProcess_comfortDemandQualifier_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
